// Internal packing only: allocation order and straddling are
// implementation-defined, so these bit positions are not portable.
struct MsgFlags {
    std::uint16_t venue : 4;
    std::uint16_t side : 1;
    std::uint16_t urgent : 1;
    std::uint16_t reserved : 10;
};

static_assert(sizeof(MsgFlags) == 2);

// Wire-facing: explicit and portable.
std::uint16_t pack_flags(std::uint16_t venue, bool sell, bool urgent) {
    return static_cast<std::uint16_t>(
        (venue & 0xFu) |
        (static_cast<std::uint16_t>(sell) << 4) |
        (static_cast<std::uint16_t>(urgent) << 5));
}

