#include <cstdint>
#include <iostream>

enum class FeedKind : std::uint8_t {
    Sim,
    Live
};

class Feed {
public:
    virtual ~Feed() = default;

    FeedKind kind() const { return kind_; }

protected:
    // Protected: only a derived class can set the tag, and it sets its own.
    explicit Feed(FeedKind kind) : kind_{kind} {}

private:
    FeedKind kind_;
};

class SimFeed : public Feed {
public:
    SimFeed() : Feed{FeedKind::Sim} {}

    void seek(std::int64_t sequence) { std::cout << sequence << '\n'; }
};

void tagged_seek(Feed& feed) {
    // The static_cast is unchecked: if the tag could ever disagree with the
    // runtime type this would be undefined behaviour. The protected
    // constructor is what enforces the agreement.
    if (feed.kind() == FeedKind::Sim) {
        static_cast<SimFeed&>(feed).seek(42);
    }
}

